import{_ as l,o as t,c as e,a2 as i}from"./chunks/framework.CsGzzEsd.js";const u=JSON.parse('{"title":"CFA 二级计划","description":"","frontmatter":{"title":"CFA 二级计划"},"headers":[],"relativePath":"zh/blogs/CFA/plan.md","filePath":"zh/blogs/CFA/plan.md"}'),n={name:"zh/blogs/CFA/plan.md"};function r(o,a,s,d,h,c){return t(),e("div",null,[...a[0]||(a[0]=[i(`<h1 id="cfa-二级学习计划" tabindex="-1">CFA 二级学习计划 <a class="header-anchor" href="#cfa-二级学习计划" aria-label="Permalink to &quot;CFA 二级学习计划&quot;">​</a></h1><blockquote><p><strong>基本假设：</strong> 备考周期 24 周，每周约 <strong>12 小时</strong>。如果考试更近，保留顺序但压缩前两个阶段；不要砍掉最后的复习与模考阶段。</p></blockquote><h2 id="完成标准" tabindex="-1">完成标准 <a class="header-anchor" href="#完成标准" aria-label="Permalink to &quot;完成标准&quot;">​</a></h2><ul><li>完成每一篇课程阅读及其章末习题。</li><li>整理一本精简的公式与错题本，而不是第二本教材。</li><li><strong>三次计时模考均达到 70% 以上</strong>，且没有任何科目反复低于 60%。</li><li>不看笔记也能讲清每种主要估值方法、其假设与常见陷阱。</li></ul><h2 id="每周节奏" tabindex="-1">每周节奏 <a class="header-anchor" href="#每周节奏" aria-label="Permalink to &quot;每周节奏&quot;">​</a></h2><table tabindex="0"><thead><tr><th>安排</th><th style="text-align:right;">时长</th><th>内容</th></tr></thead><tbody><tr><td>3 次工作日学习</td><td style="text-align:right;">每次 90 分钟</td><td>学一个概念模块，然后闭卷做 15–25 道题。</td></tr><tr><td>1 次工作日短时学习</td><td style="text-align:right;">45 分钟</td><td>公式回忆与错题本复习。</td></tr><tr><td>周末深度学习</td><td style="text-align:right;">5–6 小时</td><td>完成本科目、混合练习，并复盘一组 item set。</td></tr></tbody></table><p>采用 <strong>40/60 分配</strong>：阅读或看课不超过 40%；至少 60% 用于提取练习、计算和 item set 练习。</p><h2 id="_24-周路线图" tabindex="-1">24 周路线图 <a class="header-anchor" href="#_24-周路线图" aria-label="Permalink to &quot;24 周路线图&quot;">​</a></h2><h3 id="第-1-阶段——摸底与诊断-第-1–2-周" tabindex="-1">第 1 阶段——摸底与诊断（第 1–2 周） <a class="header-anchor" href="#第-1-阶段——摸底与诊断-第-1–2-周" aria-label="Permalink to &quot;第 1 阶段——摸底与诊断（第 1–2 周）&quot;">​</a></h3><ul><li>在 CFA 考生资源中确认考试日期和当前课程版本。</li><li>不做准备，完成一套 60–90 题的诊断测试。</li><li>为每道错题打标签：<code>knowledge</code>（知识）、<code>formula</code>（公式）、<code>interpretation</code>（理解）、<code>calculator</code>（计算器）或 <code>time</code>（时间）。</li><li>建立一个错题本：题目来源、错误答案为何看起来对、正确规则、复习日期。</li></ul><h3 id="第-2-阶段——第一轮学习-第-3–14-周" tabindex="-1">第 2 阶段——第一轮学习（第 3–14 周） <a class="header-anchor" href="#第-2-阶段——第一轮学习-第-3–14-周" aria-label="Permalink to &quot;第 2 阶段——第一轮学习（第 3–14 周）&quot;">​</a></h3><p>按能相互叠加理解的顺序学习：</p><ol><li>数量方法与经济学</li><li>财务报表分析</li><li>公司发行人</li><li>权益估值</li><li>固定收益</li><li>衍生品</li><li>另类投资</li><li>投资组合管理</li></ol><p>道德每周做一组短练习，保持手感。每学完一个科目，完成一套计时混合题，并写一页总结：关键决策、公式和易错点。</p><h3 id="第-3-阶段——整合-第-15–19-周" tabindex="-1">第 3 阶段——整合（第 15–19 周） <a class="header-anchor" href="#第-3-阶段——整合-第-15–19-周" aria-label="Permalink to &quot;第 3 阶段——整合（第 15–19 周）&quot;">​</a></h3><ul><li>用混合 item set 取代逐章学习。</li><li>每周进行两次 45–60 分钟的计时练习。</li><li>每道记录的错题在 2 天、1 周和 3 周后重做。</li><li>把相关领域配对：财报分析 ↔ 权益、经济学 ↔ 组合管理、固定收益 ↔ 衍生品。</li><li>每周结束时按科目和错误类型做一张成绩表。</li></ul><h3 id="第-4-阶段——考试模式-第-20–23-周" tabindex="-1">第 4 阶段——考试模式（第 20–23 周） <a class="header-anchor" href="#第-4-阶段——考试模式-第-20–23-周" aria-label="Permalink to &quot;第 4 阶段——考试模式（第 20–23 周）&quot;">​</a></h3><ul><li>每个周末在考试条件下完成一套完整计时模考。</li><li>复盘模考的时间至少与做题时间相同。</li><li>工作日只修补最弱的两个科目；避免漫无目的地重读。</li><li>每周凭记忆重写一次核心公式表。</li></ul><h3 id="第-5-阶段——收尾-第-24-周" tabindex="-1">第 5 阶段——收尾（第 24 周） <a class="header-anchor" href="#第-5-阶段——收尾-第-24-周" aria-label="Permalink to &quot;第 5 阶段——收尾（第 24 周）&quot;">​</a></h3><ul><li>做短而高质量的混合练习；考前几天停止整套模考。</li><li>复习道德、公式、反复出现的错误、计算器步骤和考试安排。</li><li>保证睡眠、保持信心；不再引入新资料。</li></ul><h2 id="每周复盘模板" tabindex="-1">每周复盘模板 <a class="header-anchor" href="#每周复盘模板" aria-label="Permalink to &quot;每周复盘模板&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes min-light min-dark vp-code" tabindex="0"><code><span class="line"><span>计划 / 完成小时数：</span></span>
<span class="line"><span>做题数 / 正确率：</span></span>
<span class="line"><span>最弱科目与错误模式：</span></span>
<span class="line"><span>我现在能讲给别人听的一个概念：</span></span>
<span class="line"><span>下周要做的一个调整：</span></span></code></pre></div><h2 id="前七天" tabindex="-1">前七天 <a class="header-anchor" href="#前七天" aria-label="Permalink to &quot;前七天&quot;">​</a></h2><ul><li>[ ] 记下考试日期、剩余周数和每周可用时间。</li><li>[ ] 完成诊断测试并评分。</li><li>[ ] 建立错题本和公式卡片。</li><li>[ ] 选定前两个科目模块。</li><li>[ ] 在本周开始前把所有学习时段排进日历。</li></ul><h2 id="模块笔记" tabindex="-1">模块笔记 <a class="header-anchor" href="#模块笔记" aria-label="Permalink to &quot;模块笔记&quot;">​</a></h2><p>读完本计划后，点页面底部的“下一页”进入第一篇模块笔记；全部笔记按课程顺序列在<a href="/zh/blogs/0-start.html#cfa-level-ii-directory">学习库目录</a>中。</p>`,26)])])}const b=l(n,[["render",r]]);export{u as __pageData,b as default};
